        dataSubscription = processHandle.onData((data) => {
            if (settled) return;
            pendingWrites += 1;
            terminal.write(data, () => {
                pendingWrites -= 1;
                inspectScreen();
                if (pendingExitCode !== null) settleExit(pendingExitCode);
                if (settled) disposeTerminal();
            });
        });
        exitSubscription = processHandle.onExit(({ exitCode }) => {
            exited = true;
            settleExit(exitCode);
        });
        timeout = setPollTimeout(() => {
            const screen = terminalScreenText(terminal);
            killProcess();
            // Answering trust and still not becoming ready is a different fault from never seeing the
            // screen at all, so it never triggers a second keystroke and never shares a reason.
            const reason = trustAnswered && showsTrustScreen(screen)
                ? CLAUDE_USAGE_POLL_REASONS.ptyTrustScreenUnanswered
                : CLAUDE_USAGE_POLL_REASONS.ptyNoReadyMarker;
            finishWithoutUsage(reason, screen);
        }, readyTimeoutMs);
    });
}

function createHeadlessTerminal() {
    return new Terminal({
        allowProposedApi: true,
        cols: CLAUDE_USAGE_TERMINAL_COLUMNS,
        rows: CLAUDE_USAGE_TERMINAL_ROWS,
    });
}

/**
 * Drives one `/usage` poll through a real pty and resolves with `{ payload, reason, screenExcerpt }`.
 * Only the usage worker may call this: node-pty's ConPTY layer can fault natively, which would end
 * whichever process hosts it.
 */
function runTerminalUsagePoll(request, dependencies = {}) {
    const {
        clearTimeout: clearPollTimeout = clearTimeout,
        ptySpawn = nodePty.spawn,
        registerAbort,
        setTimeout: setPollTimeout = setTimeout,
        terminalFactory = createHeadlessTerminal,
    } = dependencies;
    const processHandle = ptySpawn(request.executable, [], {
        cols: CLAUDE_USAGE_TERMINAL_COLUMNS,
        cwd: request.cwd,
        env: request.env,
        rows: CLAUDE_USAGE_TERMINAL_ROWS,
    });

    return collectTerminalUsage(processHandle, terminalFactory(), request.observedAt, {
        clearTimeout: clearPollTimeout,
        readyTimeoutMs: request.readyTimeoutMs,
        registerAbort,
        reportTimeoutMs: request.reportTimeoutMs,
        setTimeout: setPollTimeout,
    });
}

module.exports = {
    CLAUDE_USAGE_LOGIN_MARKERS,
    CLAUDE_USAGE_ONBOARDING_MARKERS,
    CLAUDE_USAGE_TERMINAL_COLUMNS,
    CLAUDE_USAGE_TERMINAL_ROWS,
    CLAUDE_USAGE_TRUST_ANSWER,
    CLAUDE_USAGE_TRUST_MARKERS,
    runTerminalUsagePoll,
};

import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { runTerminalUsagePoll } = require('./claude_usage_terminal');
const { CLAUDE_USAGE_EXCERPT_MAX_CHARS, CLAUDE_USAGE_POLL_REASONS } = require('./claude_usage_diagnostics');

const TERMINAL_USAGE_OUTPUT = `Settings  Status  Config  Usage  Stats

Current session
▌                                                  1% used
Resets 3:20pm (Europe/Brussels)

Current week (all models)
██████                                             12% used
Resets Aug 23, 7pm (Europe/Brussels)
`;
// The exact screen Claude Code 2.1.238 shows in a folder it has never run in.
const TRUST_SCREEN = `Accessing workspace:
C:\\projects\\md2
Quick safety check: Is this a project you created or one you trust?
Security guide
❯ 1. Yes, I trust this folder
  2. No, exit
Enter to confirm · Esc to cancel
`;
const LOGIN_SCREEN = 'Select login method:\r\n1. Claude account with subscription\r\n';
const ONBOARDING_SCREEN = 'Choose the text style that looks best with your terminal\r\n';
const WELCOME_SCREEN = 'Claude Code v2\r\n? for shortcuts\r\n';

const REQUEST = {
    cwd: '/project',
    env: { PATH: '/project/bin' },
    executable: 'claude.cmd',
    observedAt: Date.parse('2026-08-20T08:00:00.000Z'),
    readyTimeoutMs: 30_000,
    reportTimeoutMs: 20_000,
};

function clearScreen(text) {
    return `\u001B[2J\u001B[H${text.replaceAll('\n', '\r\n')}`;
}

function terminalChild(output = TERMINAL_USAGE_OUTPUT, exitCode = null) {
    const dataListeners = new Set();
    const exitListeners = new Set();

    return {
        kill: vi.fn(),
        onData: vi.fn((listener) => {
            dataListeners.add(listener);

            return { dispose: () => dataListeners.delete(listener) };
        }),
        onExit: vi.fn((listener) => {
            exitListeners.add(listener);
            queueMicrotask(() => dataListeners.forEach((dataListener) => dataListener(WELCOME_SCREEN)));

            return { dispose: () => exitListeners.delete(listener) };
        }),
        write: vi.fn(() => {
            queueMicrotask(() => {
                dataListeners.forEach((listener) => listener(clearScreen(output)));
                if (exitCode !== null) exitListeners.forEach((listener) => listener({ exitCode }));
            });
        }),
    };
}

/** A pty that starts on the trust screen and only reaches the welcome screen once it is answered. */
function trustingChild({ answerLeadsToWelcome = true } = {}) {
    const dataListeners = new Set();
    const exitListeners = new Set();
    const emit = (text) => dataListeners.forEach((listener) => listener(clearScreen(text)));
    const handle = {
        kill: vi.fn(),
        onData: vi.fn((listener) => {
            dataListeners.add(listener);

            return { dispose: () => dataListeners.delete(listener) };
        }),
        onExit: vi.fn((listener) => {
            exitListeners.add(listener);
            queueMicrotask(() => emit(TRUST_SCREEN));

            return { dispose: () => exitListeners.delete(listener) };
        }),
        write: vi.fn((data) => {
            if (data === '\r') {
                // Answering trust either lands on the welcome screen or leaves the same screen up.
                queueMicrotask(() => emit(answerLeadsToWelcome ? WELCOME_SCREEN : TRUST_SCREEN));
                return;
            }
            queueMicrotask(() => emit(TERMINAL_USAGE_OUTPUT));
        }),
    };

    return handle;
}

